"""Verify the committed Gradle 8.14.3 wrapper before executing it. No network needed."""
import argparse
import hashlib
import os
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
# Distribution/JAR values: https://gradle.org/release-checksums/ (8.14.3).
DISTRIBUTION_SHA256 = 'bd71102213493060956ec229d946beee57158dbd89d0e62b91bca0fa2c5f3531'
JAR_SHA256 = '7d3a4ac4de1c32b59bc6a4eb8ecb8e612ccd0cf1ae1e99f66902da64df296172'
# Launchers generated by the checksum-verified Gradle 8.14.3 distribution.
LAUNCHERS = {'gradlew': 'b187b4c52e749f5760afdd6fadc31b2a98ad35fb249bf0dff03b72650f320409',
             'gradlew.bat': '94102713eb8fb22d032397924c0f38ab2da783ba60d07054339f1190a0c4e2cd'}
PROPERTIES = {
    'distributionBase': 'GRADLE_USER_HOME', 'distributionPath': 'wrapper/dists',
    'distributionSha256Sum': DISTRIBUTION_SHA256,
    'distributionUrl': 'https://services.gradle.org/distributions/gradle-8.14.3-bin.zip',
    'networkTimeout': '10000', 'validateDistributionUrl': 'true',
    'zipStoreBase': 'GRADLE_USER_HOME', 'zipStorePath': 'wrapper/dists',
}


def safe_file(bridge, relative):
    path = bridge / relative
    if not path.is_file() or any(p.is_symlink() for p in (path, *list(path.parents)[:len(Path(relative).parts)])):
        raise ValueError('Missing or symlinked wrapper file: ' + relative)
    return path


def verify(bridge):
    jar = safe_file(bridge, 'gradle/wrapper/gradle-wrapper.jar')
    if hashlib.sha256(jar.read_bytes()).hexdigest() != JAR_SHA256:
        raise ValueError('Wrapper JAR checksum mismatch')
    for name, expected in LAUNCHERS.items():
        data = safe_file(bridge, name).read_bytes()
        if name.endswith('.bat'): data = data.replace(b'\r\n', b'\n')
        if hashlib.sha256(data).hexdigest() != expected:
            raise ValueError('Wrapper launcher checksum mismatch: ' + name)
    if os.name != 'nt' and not os.access(bridge / 'gradlew', os.X_OK):
        raise ValueError('gradlew is not executable')
    properties = {}
    for line in safe_file(bridge, 'gradle/wrapper/gradle-wrapper.properties').read_text().splitlines():
        if not line.strip() or line.lstrip().startswith('#'): continue
        key, separator, value = line.partition('=')
        if not separator or key in properties: raise ValueError('Malformed or duplicate wrapper property')
        properties[key] = value.replace('\\:', ':')
    if properties != PROPERTIES:
        raise ValueError('Wrapper properties differ from reviewed Gradle 8.14.3 configuration')


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--bridge', type=Path, default=ROOT / 'bridge')
    args = parser.parse_args(argv)
    try:
        verify(args.bridge)
        print('Gradle 8.14.3 wrapper verified (launchers, JAR, distribution URL and SHA-256).')
        return 0
    except (OSError, ValueError) as error:
        print('Wrapper verification failed: ' + str(error), file=sys.stderr)
        return 1
